package com.networkers.meetingautomation;
import com.networkers.user.User; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="monthly_meeting_comments") public class MeetingComment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private MonthlyMeeting meeting; @ManyToOne(optional=false) private User author; @Column(nullable=false,length=1500) private String text; private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public MonthlyMeeting getMeeting(){return meeting;} public void setMeeting(MonthlyMeeting v){meeting=v;} public User getAuthor(){return author;} public void setAuthor(User v){author=v;} public String getText(){return text;} public void setText(String v){text=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
